// resolveRepoRef turns a repo reference into its ULID. A ULID passes through.
// A name requires a project scope (projectRef, itself a name or ULID) because
// repo names are unique only within a project.
//
// Unlike org/project resolution, the repo lookup matches client-side: it lists
// the project's repos (the same call `entire repo list` makes) and matches the
// name case-insensitively. The server's `?name=` exact-match filter on this
// endpoint is unreliable — it returns no match for repos that plainly exist
// (COR-699) — so the CLI does not depend on it. Repo counts per project are
// small, so listing in full is cheap.
func resolveRepoRef(ctx context.Context, c *coreapi.Client, ref, projectRef string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	if projectRef == "" {
		return "", fmt.Errorf("repo %q is a name; pass --project <name|ULID> to resolve it, or use a repo ULID", ref)
	}
	projID, err := resolveProjectRef(ctx, c, projectRef)
	if err != nil {
		return "", err
	}
	repos, err := fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Repo, string, error) {
		params := coreapi.ListProjectReposParams{ProjectId: projID}
		if cursor != "" {
			params.PageToken = coreapi.NewOptString(cursor)
		}
		out, err := c.ListProjectRepos(ctx, params)
		if err != nil {
			return nil, "", err
		}
		return out.Repos, out.NextPageToken.Or(""), nil
	})
	if err != nil {
		if isCoreNotFound(err) {
			return "", noRepoNamedErr(ref)
		}
		return "", err
	}
	for _, r := range repos {
		if strings.EqualFold(r.Name, ref) {
			return r.ID, nil
		}
	}
	return "", noRepoNamedErr(ref)
}

